INSERT INTO tea_regions (name, province, climate, famous_for, description) VALUES
    ('福建省', '福建省', '亚热带季风气候，温暖湿润，多山多雾，武夷山、戴云山等山脉提供优质茶园微气候', '[{"name":"铁观音","category":"乌龙茶","origin":"泉州安溪","description":"半发酵乌龙茶，\"七泡有余香\"，兰花香显著，音韵独特，1725年前后创制"},{"name":"大红袍","category":"乌龙茶","origin":"南平武夷山","description":"武夷岩茶之王，岩骨花香，母树仅6株，2006年起停止采摘母树，现为无性繁殖后代"},{"name":"正山小种","category":"红茶","origin":"南平武夷山桐木关","description":"世界红茶鼻祖，16世纪末创制，松烟香桂圆汤味，桐木关为原产地核心保护区"},{"name":"白毫银针","category":"白茶","origin":"宁德福鼎","description":"白茶之王，全芽头制成，不炒不揉，满披白毫，\"一年茶三年药七年宝\""}]'::jsonb, '福建是中国乌龙茶、白茶、红茶的发源地，武夷山是世界文化与自然双遗产，"武夷岩茶（大红袍）制作技艺"2006年列入首批国家级非物质文化遗产。闽南功夫茶是中国最具代表性的茶艺形式之一，"关公巡城""韩信点兵"等招式流传至今。'),
    ('广东省', '广东省', '亚热带季风气候，高温多雨，凤凰山、罗浮山等山区云雾缭绕，适宜茶树生长', '[{"name":"凤凰单丛","category":"乌龙茶","origin":"潮州凤凰山","description":"半发酵乌龙茶，以\"一树一香\"著称，有蜜兰香、鸭屎香、黄枝香等数十种香型，宋种古树树龄超600年"},{"name":"英德红茶","category":"红茶","origin":"清远英德","description":"全发酵红茶，1959年创制，\"中国红茶之乡\"，浓强鲜爽，曾为英国皇室用茶"}]'::jsonb, '广东潮汕功夫茶是中国茶艺的活化石，"高冲低洒、盖沫重眉、关公巡城、韩信点兵"二十四式流传数百年。潮州凤凰单丛的"单株采制"工艺是乌龙茶中最精细的制作方式。'),
    ('广西壮族自治区', '广西壮族自治区', '亚热带季风气候，温暖湿润，梧州、横县等地丘陵广布，土壤肥沃', '[{"name":"六堡茶","category":"黑茶","origin":"梧州六堡镇","description":"后发酵黑茶，\"红浓陈醇\"，槟榔香显著，清嘉庆年间已成为名茶，通过\"茶船古道\"远销南洋"},{"name":"横县茉莉花茶","category":"再加工茶","origin":"南宁横州市","description":"中国最大茉莉花茶产区，\"中国茉莉之乡\"，窨制工艺精湛，花香茶韵交融"}]'::jsonb, '六堡茶是海上丝绸之路和茶船古道的重要商品，梧州六堡茶制作技艺2014年列入国家级非物质文化遗产。横县茉莉花茶文化节每年吸引大量游客。'),
    ('海南省', '海南省', '热带季风气候，全年高温多雨，五指山、白沙等地山区云雾多，是中国最南端的茶区', '[{"name":"白沙绿茶","category":"绿茶","origin":"白沙黎族自治县","description":"不发酵绿茶，产于白沙陨石坑周边，土壤富含矿物质，\"中国国家地理标志产品\""},{"name":"五指山红茶","category":"红茶","origin":"五指山","description":"全发酵红茶，高山云雾茶，蜜香浓郁，2015年获\"国家农产品地理标志\"登记"}]'::jsonb, '海南是中国唯一的热带茶区，茶树全年可采摘，白沙陨石坑茶园是世界上少有的陨石坑茶园。黎族苗族同胞有悠久的饮茶文化。'),
    ('台湾省', '台湾省', '亚热带至热带季风气候，高山多雾，昼夜温差大，阿里山、日月潭、冻顶山等高山茶区品质优异', '[{"name":"冻顶乌龙","category":"乌龙茶","origin":"南投鹿谷冻顶山","description":"半发酵乌龙茶，台湾乌龙茶代表，19世纪从福建武夷山引入茶种，茶汤金黄，蜜花香"},{"name":"东方美人","category":"乌龙茶","origin":"新竹北埔、峨眉","description":"半发酵乌龙茶，又称\"白毫乌龙\"\"香槟乌龙\"，需小绿叶蝉叮咬后采摘，英国维多利亚女王赐名\"东方美人\""},{"name":"日月潭红茶","category":"红茶","origin":"南投鱼池乡","description":"全发酵红茶，日据时期从印度引入阿萨姆种，\"台茶18号\"红玉有薄荷肉桂香"}]'::jsonb, '台湾茶文化融合闽南功夫茶与日式茶道，"奉茶"文化深入人心。台北猫空、南投溪头是著名茶旅目的地。高山茶（海拔1000米以上）是台湾茶的品质标杆。'),
    ('云南省', '云南省', '立体气候显著，西双版纳、普洱、临沧等地高温多雨，古茶树资源丰富，是世界茶树原产地核心区', '[{"name":"普洱茶","category":"黑茶","origin":"西双版纳、普洱、临沧","description":"后发酵黑茶，以云南大叶种晒青毛茶为原料，分生茶（自然陈化）和熟茶（人工渥堆发酵），\"越陈越香\""},{"name":"滇红","category":"红茶","origin":"临沧凤庆","description":"全发酵红茶，1939年创制，大叶种原料，金毫显露，浓强鲜爽，\"世界滇红之乡\"凤庆"}]'::jsonb, '云南是世界茶树原产地，镇沅千家寨有2700年树龄的野生古茶树王，勐海布朗山有千年栽培型古茶园。普洱茶"茶马古道"是古代西南丝绸之路的重要通道。傣族、哈尼族、彝族等少数民族有丰富的饮茶习俗。'),
    ('贵州省', '贵州省', '亚热带季风气候，"天无三日晴"，多云雾寡日照，高海拔低纬度，茶叶内含物质丰富', '[{"name":"都匀毛尖","category":"绿茶","origin":"黔南都匀","description":"不发酵绿茶，\"三绿三黄\"（干茶绿中带黄、汤色绿中透黄、叶底绿中显黄），1915年巴拿马万国博览会获奖"},{"name":"湄潭翠芽","category":"绿茶","origin":"遵义湄潭","description":"不发酵绿茶，扁平光滑，形似葵花籽，栗香持久，\"中国名茶之乡\"湄潭"}]'::jsonb, '贵州是中国古茶树资源大省，普安有百万年四球古茶籽化石。1939年民国政府在湄潭建立"中央实验茶场"，是中国现代茶业的摇篮之一。贵州茶以"干净茶"著称，农药残留控制严格。'),
    ('四川省', '四川省', '亚热带季风气候，盆地多云雾，雅安、峨眉山、蒙顶山等山区湿润多雾，是中国最早的茶区之一', '[{"name":"蒙顶甘露","category":"绿茶","origin":"雅安蒙山","description":"不发酵绿茶，中国最古老的名茶之一，西汉吴理真在蒙顶山植茶被尊为\"植茶始祖\"，\"扬子江中水，蒙山顶上茶\""},{"name":"竹叶青","category":"绿茶","origin":"乐山峨眉山","description":"不发酵绿茶，扁平挺直似竹叶，1964年陈毅元帅命名，\"论道\"\"静心\"等系列高端化运营"}]'::jsonb, '四川是中国茶文化的发源地之一，西汉王褒《僮约》中"烹茶尽具""武阳买茶"是世界最早的茶叶买卖记载。成都盖碗茶是川渝茶文化的标志，"长嘴壶茶艺"是国家级非物质文化遗产。'),
    ('西藏自治区', '西藏自治区', '高原气候，易贡、察隅等地海拔较低、气候湿润，是世界上海拔最高的茶区之一', '[{"name":"易贡茶","category":"绿茶","origin":"林芝易贡","description":"不发酵绿茶，产于海拔2200-2500米的易贡茶场，是世界海拔最高的有机茶场之一，1960年新疆生产建设兵团援建"}]'::jsonb, '藏族有悠久的酥油茶文化，"宁可三日无粮，不可一日无茶"。茶叶通过茶马古道从四川、云南输入西藏，是汉藏文化交流的重要纽带。易贡茶场的建立改变了西藏不产茶的历史。'),
    ('浙江省', '浙江省', '亚热带季风气候，温暖湿润，西湖、安吉、龙井村等地丘陵缓坡，土壤呈微酸性，适宜茶树生长', '[{"name":"西湖龙井","category":"绿茶","origin":"杭州西湖","description":"不发酵绿茶，中国十大名茶之首，\"色绿、香郁、味甘、形美\"四绝，狮峰、龙井、云栖、虎跑、梅家坞五大核心产区"},{"name":"安吉白茶","category":"绿茶","origin":"湖州安吉","description":"不发酵绿茶（虽名\"白茶\"实为绿茶工艺），白叶一号品种，春季芽叶白化，氨基酸含量高，鲜爽甘甜"}]'::jsonb, '浙江是中国绿茶核心产区，杭州西湖龙井村有18棵"御茶树"（清乾隆册封）。陆羽在浙江湖州撰写世界第一部茶学专著《茶经》。径山寺是日本茶道的源头之一，"径山茶宴"2022年列入人类非物质文化遗产。'),
    ('湖南省', '湖南省', '亚热带季风气候，温暖湿润，安化、岳阳、湘西等地山区云雾多，土壤富含矿物质', '[{"name":"君山银针","category":"黄茶","origin":"岳阳洞庭湖君山岛","description":"轻发酵黄茶，中国十大名茶之一，全芽头制成，\"金镶玉\"，冲泡时\"三起三落\"，黄茶工艺代表"},{"name":"安化黑茶","category":"黑茶","origin":"益阳安化","description":"后发酵黑茶，\"千两茶\"\"茯砖茶\"\"黑砖茶\"等，茯砖茶有\"金花\"（冠突散囊菌），古代\"茶马互市\"的主要商品"}]'::jsonb, '湖南是中国黑茶和黄茶的核心产区。安化黑茶制作技艺2008年列入国家级非物质文化遗产。君山银针的黄茶"闷黄"工艺是中国独有的制茶工艺。长沙马王堆汉墓出土了随葬茶叶，证明湖南饮茶历史悠久。'),
    ('江西省', '江西省', '亚热带季风气候，温暖湿润，庐山、婺源、井冈山等山区云雾缭绕，生态环境优良', '[{"name":"庐山云雾","category":"绿茶","origin":"九江庐山","description":"不发酵绿茶，中国十大名茶之一，高山云雾茶，\"香馨、味厚、色翠、汤清\"，东汉时已有茶树栽培"},{"name":"婺源绿茶","category":"绿茶","origin":"上饶婺源","description":"不发酵绿茶，\"中国最美乡村\"婺源产，\"茗眉\"\"仙枝\"等品种，明清时期为贡品，\"唐载茶经，宋称绝品，明清入贡\""}]'::jsonb, '江西是中国茶文化的重要发源地之一，庐山白鹿洞书院、东林寺有悠久的饮茶传统。婺源绿茶通过"新安江-富春江"水路远销杭州、上海。景德镇陶瓷与江西茶文化相辅相成，"白如玉、明如镜"的瓷器是最佳茶器。'),
    ('安徽省', '安徽省', '亚热带季风气候，黄山、祁门、六安、太平等地山区多云雾，昼夜温差大，茶叶品质优异', '[{"name":"黄山毛峰","category":"绿茶","origin":"黄山","description":"不发酵绿茶，中国十大名茶之一，\"白毫披身，芽尖似峰\"，清光绪年间谢裕大茶庄创制，高山云雾茶"},{"name":"祁门红茶","category":"红茶","origin":"黄山祁门","description":"全发酵红茶，世界三大高香红茶之一（与印度大吉岭、斯里兰卡乌伐齐名），\"祁门香\"似花似果似蜜，1875年创制"},{"name":"太平猴魁","category":"绿茶","origin":"黄山黄山区","description":"不发酵绿茶，两叶抱一芽，扁平挺直，\"猴韵\"独特，中国十大名茶之一，核心产区仅猴坑、猴岗、颜家三个自然村"},{"name":"六安瓜片","category":"绿茶","origin":"六安金寨、霍山","description":"不发酵绿茶，中国十大名茶中唯一无芽无梗的单片叶茶，\"拉老火\"工艺独特，清代为贡品，\"齐山云雾\"品质最佳"}]'::jsonb, '安徽是中国名茶最集中的省份之一，黄山地区是中国绿茶和红茶的核心产区。祁门红茶在1915年巴拿马万国博览会获金奖，曾为英国皇室下午茶用茶。徽州文化中的"茶礼""茶祭"习俗源远流长。'),
    ('江苏省', '江苏省', '亚热带季风气候，温暖湿润，苏州洞庭山、南京、金坛等地丘陵地区适宜茶树生长', '[{"name":"碧螺春","category":"绿茶","origin":"苏州太湖洞庭山","description":"不发酵绿茶，中国十大名茶之一，\"条索纤细，卷曲成螺，满身披毫，银白隐翠\"，清康熙皇帝赐名\"碧螺春\"，茶果间作，有花果香"},{"name":"南京雨花茶","category":"绿茶","origin":"南京","description":"不发酵绿茶，1958年创制，形似松针，象征革命先烈坚贞不屈，\"中国十大名茶\"之一"}]'::jsonb, '江苏茶文化源远流长，苏州洞庭山碧螺春的"茶果间作"模式（茶树与枇杷、杨梅、柑橘等果树混种）是中国独特的茶园生态模式。南京雨花茶是新中国成立后创制的名茶，具有特殊的历史意义。'),
    ('湖北省', '湖北省', '亚热带季风气候，温暖湿润，恩施、宜昌、武当山等地山区云雾多，土壤含硒量高', '[{"name":"恩施玉露","category":"绿茶","origin":"恩施","description":"不发酵绿茶，中国唯一保留的蒸青绿茶工艺（唐代传至日本），\"色绿、汤绿、叶绿\"三绿，恩施富硒茶代表"},{"name":"宜昌红茶","category":"红茶","origin":"宜昌","description":"全发酵红茶，\"宜红\"是中国三大工夫红茶之一（与祁红、滇红齐名），19世纪中叶出口欧洲，\"万里茶道\"重要商品"}]'::jsonb, '湖北是"万里茶道"的重要节点，宜昌、汉口是近代中国最大的茶叶集散地。恩施玉露的蒸青工艺是唐代制茶法的活化石，与日本抹茶、煎茶工艺同源。武当山道茶有悠久的道教茶文化传统。'),
    ('河南省', '河南省', '暖温带至亚热带过渡气候，信阳大别山区云雾多，昼夜温差大，是中国最北的茶区之一', '[{"name":"信阳毛尖","category":"绿茶","origin":"信阳","description":"不发酵绿茶，中国十大名茶之一，\"细、圆、紧、直、多白毫\"，1915年巴拿马万国博览会获金奖，\"绿茶之王\"，核心产区车云山、集云山、云雾山等\"五云两潭一寨\""}]'::jsonb, '信阳是中国最北的名茶产区，"淮南茶，信阳第一"（北宋苏轼语）。信阳毛尖制作技艺2021年列入国家级非物质文化遗产。信阳茶文化节每年4月举办，是中国重要的茶事活动。'),
    ('陕西省', '陕西省', '北亚热带气候，安康、汉中等地秦巴山区云雾多，土壤含硒，是中国最北的茶区之一', '[{"name":"紫阳富硒茶","category":"绿茶","origin":"安康紫阳","description":"不发酵绿茶，中国唯一通过科学鉴定的富硒茶产区，土壤天然含硒，\"中国名茶之乡\"，唐代已为贡品"},{"name":"汉中仙毫","category":"绿茶","origin":"汉中","description":"不发酵绿茶，\"午子仙毫\"\"定军茗眉\"\"宁强雀舌\"整合品牌，\"中国国家地理标志产品\"，高山云雾茶"}]'::jsonb, '陕西是中国茶文化的重要发源地，西安是唐代长安城，陆羽《茶经》中记载"山南茶区"包括汉中、安康。紫阳富硒茶的发现改变了中国缺硒地区的营养结构。陕南茶区是"茶马古道"的北线起点。'),
    ('甘肃省', '甘肃省', '温带大陆性气候，陇南文县、武都等地海拔较低、气候湿润，是中国最北的茶区', '[{"name":"陇南绿茶","category":"绿茶","origin":"陇南文县、武都、康县","description":"不发酵绿茶，\"甘肃唯一产茶区\"，海拔600-1200米，\"碧口龙井\"\"李子坝毛尖\"等品种，高山云雾茶，内含物质丰富"}]'::jsonb, '陇南是甘肃唯一的产茶区，有"陇上江南"之称。文县碧口镇是甘肃茶叶的核心产区，茶马古道从这里进入甘肃。陇南茶区的存在证明了中国茶树种植的北界可达北纬33度。'),
    ('山东省', '山东省', '温带季风气候，日照、青岛等地沿海地区湿润多雾，是"南茶北引"成功的典范', '[{"name":"日照绿茶","category":"绿茶","origin":"日照","description":"不发酵绿茶，1966年\"南茶北引\"成功，\"中国绿茶新贵\"，栗香浓郁，耐冲泡，纬度最高的茶区之一，昼夜温差大"},{"name":"崂山绿茶","category":"绿茶","origin":"青岛崂山","description":"不发酵绿茶，1958年\"南茶北引\"，崂山矿泉水灌溉，\"豌豆香\"独特，\"中国国家地理标志产品\""}]'::jsonb, '山东是"南茶北引"工程的成功典范，1950-60年代从安徽、浙江引入茶种，在日照、青岛、临沂等地试种成功。日照绿茶已成为山东农业的名片之一。山东人饮茶以茉莉花茶和绿茶为主，济南是北方最大的茶叶集散地。');
INSERT INTO tea_processes (tea_category, name, summary, steps) VALUES
    ('绿茶', '绿茶制作工艺', '绿茶为不发酵茶，核心工艺是"杀青"——通过高温破坏鲜叶中的氧化酶活性，保持茶叶的绿色。', '[{"order":1,"name":"采摘","description":"采摘一芽一叶或一芽二叶，明前茶为品质最佳。采摘要\"三不采\"：不采雨水叶、不采病虫害叶、不采紫色叶。","duration":"春季3-4月","temperature":"常温"},{"order":2,"name":"摊青","description":"鲜叶均匀摊放在竹席上，自然散失部分水分，使叶片柔软，便于后续杀青。","duration":"2-4小时"},{"order":3,"name":"杀青","description":"在高温锅中翻炒鲜叶（炒青）或用蒸汽蒸制（蒸青），破坏氧化酶活性，停止发酵。锅温约200°C，手法有\"抖、搭、捺、推\"等。","duration":"5-10分钟","temperature":"180-220°C"},{"order":4,"name":"揉捻","description":"将杀青后的茶叶趁热揉捻，使茶叶卷曲成条，同时揉出茶汁附着在叶面，增加冲泡时的滋味。","duration":"15-30分钟"},{"order":5,"name":"干燥","description":"通过烘干或炒干进一步去除水分，固定茶形，提升香气。使含水量降至5%以下。","duration":"30-60分钟","temperature":"80-120°C"}]'::jsonb),
    ('白茶', '白茶制作工艺', '白茶为微发酵茶，制作工艺最为自然简洁——不炒不揉，只经萎凋和干燥，最大程度保留了茶叶的本真。', '[{"order":1,"name":"采摘","description":"白毫银针只采单芽，白牡丹采一芽一二叶。采摘要选择晴朗天气，保证萎凋品质。","duration":"春季3-4月"},{"order":2,"name":"萎凋","description":"将鲜叶均匀摊放在竹帘上，置于通风处自然萎凋。这是白茶品质形成的关键步骤，需要72小时左右。期间茶叶缓慢失水，内含物质发生微妙转化。","duration":"48-72小时","temperature":"20-30°C"},{"order":3,"name":"干燥","description":"用文火低温烘干，进一步去除水分，固定品质。传统用焙笼炭火烘焙。","duration":"1-2小时","temperature":"40-50°C"}]'::jsonb),
    ('黄茶', '黄茶制作工艺', '黄茶的独特之处在于"闷黄"——在杀青后用湿布包裹茶叶，让其在湿热条件下发生非酶性氧化，使茶叶和汤色变成黄色。', '[{"order":1,"name":"采摘","description":"采摘一芽一叶或一芽二叶，以春茶品质最佳。","duration":"春季"},{"order":2,"name":"杀青","description":"与绿茶类似，用高温破坏氧化酶活性。温度略低于绿茶。","temperature":"160-180°C"},{"order":3,"name":"闷黄","description":"将杀青后的茶叶用湿纸或湿布包裹，放置数小时至数天。在温热条件下，叶绿素被破坏，叶色由绿变黄，形成黄茶特有的\"黄叶黄汤\"。","duration":"4-48小时","temperature":"30-40°C"},{"order":4,"name":"干燥","description":"低温慢烘，固定色香味。","duration":"1-2小时"}]'::jsonb),
    ('青茶', '乌龙茶（青茶）制作工艺', '乌龙茶为半发酵茶，制作工艺最为复杂精细——通过"做青"使叶缘发酵形成"绿叶红镶边"的独特品质。萎凋、摇青、炒青、揉捻、烘焙等工序环环相扣。', '[{"order":1,"name":"采摘","description":"采摘开面三四叶，以晴天的下午采摘要最佳。岩茶讲究\"三不采\"：不采雨水青、不采露水青、不采烈日青。","duration":"春秋两季"},{"order":2,"name":"萎凋","description":"将鲜叶薄摊于竹筛上，置于日光下或室内自然萎凋，使叶片柔软、水分蒸发。","duration":"1-2小时"},{"order":3,"name":"做青（摇青）","description":"将茶叶放入竹制摇笼中交替进行\"摇青\"和\"静置\"——摇青使叶缘碰撞破裂，静置使内含物质转化。这个过程需要重复5-10次，持续8-12小时。乌龙茶的香气和品质在此阶段形成。","duration":"8-12小时"},{"order":4,"name":"杀青","description":"用高温炒锅破坏发酵酶的活性，固定做青成果，停止发酵。","duration":"5-8分钟","temperature":"200-240°C"},{"order":5,"name":"揉捻","description":"趁热将茶叶揉捻成条（包揉），使茶汁渗出，卷曲紧结。","duration":"15-30分钟"},{"order":6,"name":"初烘","description":"初步烘焙去除水分，固定形状。","duration":"30-60分钟","temperature":"80-100°C"},{"order":7,"name":"复焙（炭焙）","description":"这是岩茶品质升华的关键步骤。用炭火长时间低温慢焙，使茶香内敛、汤感醇厚。不同火工（轻火/中火/足火）决定乌龙茶的风格。","duration":"2-8小时","temperature":"60-120°C"}]'::jsonb),
    ('红茶', '红茶制作工艺', '红茶为全发酵茶，核心工艺是"发酵"——在适宜温湿度下让茶叶充分氧化，使茶汤和叶底呈现红色，形成甜醇的风味。', '[{"order":1,"name":"采摘","description":"采摘一芽二三叶，以春茶和秋茶品质最佳。","duration":"春、夏、秋三季"},{"order":2,"name":"萎凋","description":"将鲜叶摊放在萎凋槽中，通热风促进水分蒸发，使叶片柔软、香气显露。","duration":"6-12小时"},{"order":3,"name":"揉捻","description":"用揉捻机使茶叶卷曲成条，破坏叶细胞结构，使茶汁外溢，促进发酵。","duration":"30-60分钟"},{"order":4,"name":"发酵","description":"在发酵室中保持高湿度（95%以上）和适宜温度，茶叶在酶的作用下充分氧化。叶色由绿转红，香气由青草香变为花果香。","duration":"2-5小时","temperature":"25-30°C"},{"order":5,"name":"干燥","description":"高温烘干终止发酵，固定品质，使含水量降至5%以下。","duration":"30-60分钟","temperature":"90-120°C"}]'::jsonb),
    ('黑茶', '黑茶制作工艺', '黑茶为后发酵茶，核心工艺是"渥堆"——将茶叶堆放在一起洒水，在微生物作用下进行发酵。普洱熟茶的"渥堆发酵"是黑茶中最具代表性的工艺。', '[{"order":1,"name":"采摘","description":"采摘一芽三四叶或对夹叶，以粗老叶片为主。","duration":"夏秋季为主"},{"order":2,"name":"杀青","description":"用高温铁锅翻炒杀青，破坏氧化酶活性。","temperature":"180-200°C"},{"order":3,"name":"揉捻","description":"趁热揉捻成条，使茶汁渗出。黑茶的揉捻一般较重。","duration":"20-40分钟"},{"order":4,"name":"渥堆（核心）","description":"将揉捻后的茶叶堆成一定厚度（30-50厘米），洒水后盖上湿布，在微生物和湿热作用下后发酵。期间堆温会自然上升到50-65°C，需要定期翻堆控制温湿度。这是普洱茶\"越陈越香\"品质形成的关键。","duration":"45-60天","temperature":"50-65°C"},{"order":5,"name":"干燥","description":"自然晾干或低温烘干，使含水量降至12%以下。","duration":"3-7天"},{"order":6,"name":"紧压（可选）","description":"将干燥后的茶叶蒸软后压制成饼、砖、沱等形状，便于存放和运输。","duration":"根据形状"}]'::jsonb);
INSERT INTO teas (name, category, origin, altitude, best_temp, best_time, infusions, flavor, story, description, soup_color_min, soup_color_max, dry_tea_color) VALUES
    ('西湖龙井', '绿茶', '浙江杭州', '300-800米', 80, 60, 3, '["豆香","栗香","鲜爽"]'::jsonb, '西湖龙井居中国名茶之首，历史可溯至唐代陆羽《茶经》。乾隆皇帝六下江南，四次驾临龙井茶区，亲封狮峰山脚下十八棵茶树为"御茶"，并题诗《观采茶作歌》："火前嫩，火后老，惟有骑火品最好。"龙井茶扁平光滑、色翠香郁，以"色绿、香郁、味甘、形美"四绝闻名于世。苏轼任杭州知州时曾咏"白云峰下两旗新，腻绿长鲜谷雨春"——说的便是谷雨前的龙井。', '中国十大名茶之首，扁平光滑，色泽翠绿，香气清高，四绝闻名天下。', '#F5E6A3', '#C9B458', '#4A7C59'),
    ('碧螺春', '绿茶', '江苏苏州', '100-300米', 75, 45, 3, '["花果香","清甜","鲜嫩"]'::jsonb, '碧螺春原名"吓煞人香"，因茶香惊人而得名。清康熙三十八年（1699年），康熙帝南巡至太湖，品尝此茶后赞不绝口，但觉其名粗俗，遂据其"色泽碧绿、形似螺旋、采于早春"的特征，赐名"碧螺春"。太湖洞庭山气候温润，茶果间作——茶树与枇杷、杨梅等果树交错生长，茶叶天然吸附花果之香，形成了碧螺春独一无二的"花果香"。', '产于太湖洞庭山，茶叶卷曲如螺，银绿隐翠，花果香天然天成。', '#E8F5E9', '#A5D6A7', '#6B8E23'),
    ('黄山毛峰', '绿茶', '安徽黄山', '700-1200米', 80, 50, 3, '["兰花香","清鲜","甘甜"]'::jsonb, '黄山毛峰创制于清光绪年间（1875年），由徽州茶商谢裕大茶庄创制。黄山自古以奇松、怪石、云海、温泉闻名，茶树生长在高山云雾之中，"晴时早晚遍地雾，阴雨成天满山云"，得天独厚的自然环境孕育了黄山毛峰独特的品质。明代茶人许次纾在《茶疏》中赞黄山茶："若吴之虎丘、钱塘之龙井，香气芬芳，皆在云雾中。"', '中国十大名茶之一，白毫披身，芽尖锋芒，汤色清澈微黄。', '#F0F5E8', '#B8C9A8', '#5B8C5A'),
    ('信阳毛尖', '绿茶', '河南信阳', '500-800米', 75, 40, 3, '["板栗香","鲜爽","回甘"]'::jsonb, '信阳毛尖又称"豫毛峰"，是中国十大名茶中唯一的北方茶。信阳地处南北气候过渡带，"淮南茶，信阳第一"——宋代大文豪苏东坡谪居黄州时尝遍各地名茶，独推信阳茶为冠。1915年，信阳毛尖代表中国茶参加巴拿马万国博览会，一举夺得金质奖章，让世界见识了中国北方茶的非凡品质。', '中国十大名茶之一，细圆光直，白毫显露，汤色嫩绿明亮。', '#E8F5E0', '#A8C99A', '#6B9E5A'),
    ('太平猴魁', '绿茶', '安徽太平', '400-800米', 85, 50, 3, '["兰花香","鲜爽","醇厚"]'::jsonb, '太平猴魁创制于1900年，以其"两刀夹一芽"的独特外形和"猴魁两头尖"的形态著称于世。民间相传，古时太平县有猴群采野茶献于山中隐士，隐士感其灵性，精心制茶，茶香惊动四邻，遂得名"猴魁"。其叶片长达5-7厘米，为中国绿茶中叶片最大者，有"茶中君子"之称。1955年，太平猴魁被评为中国十大名茶之一。', '中国十大名茶之一，叶片长达5-7厘米，有"茶中君子"之称。', '#EAF0E0', '#B8CAA0', '#6B9A5A'),
    ('白牡丹', '白茶', '福建福鼎', '600-1000米', 90, 90, 5, '["毫香","花香","清甜"]'::jsonb, '白茶是中国六大茶类中制作工艺最简单、最接近自然的一类——不炒不揉，只经萎凋和干燥，最大程度保留了茶叶的本真。白牡丹选用一芽一二叶为原料，芽叶连枝如花朵般舒展，故得此雅名。宋代皇帝徽宗赵佶在《大观茶论》中论白茶："白茶自为一种，与常茶不同，其条敷阐，其叶莹薄。"宋代贡茶中已有白茶的记载，距今已逾千年。', '白茶中的极品，芽叶连枝似花，满披白毫，如银似雪。', '#F0E68C', '#DAA520', '#8B9A6B'),
    ('白毫银针', '白茶', '福建福鼎', '600-1000米', 85, 120, 5, '["毫香","清甜","鲜爽"]'::jsonb, '白毫银针是白茶中的极品，全部采用肥壮单芽制成，满披白毫如银似雪，素有"茶中美女"之称。清代嘉庆年间，白毫银针即已远销海外，在欧洲贵族茶单中占有一席之地。白茶不炒不揉，最接近自然本味，品饮时讲究"甘、鲜、清、爽"四字。', '白茶之王，芽头肥壮挺直，满披白毫如银似雪，汤色浅杏黄。', '#F5F0D8', '#D4C89A', '#9AAD8A'),
    ('君山银针', '黄茶', '湖南岳阳', '100-200米', 85, 75, 4, '["甜香","玉米香","醇和"]'::jsonb, '君山银针产于洞庭湖中的君山岛，是中国黄茶中最负盛名的代表。泡入杯中可见"三起三落"的奇观——银针先浮于水面，后缓缓下沉，再复上浮，如此三次，如舞者翩跹，令人叹为观止。君山岛孤悬洞庭湖中，刘禹锡《望洞庭》"遥望洞庭山水翠，白银盘里一青螺"写的便是这湖中山色。君山银针在清代被列为贡茶，1956年莱比锡世界博览会上获得金奖，是中国黄茶走向世界的标志。', '黄茶中的珍品，芽头肥壮，满披白毫，冲泡时三起三落，堪称茶中奇观。', '#FFE4B5', '#F4A460', '#C9A96E'),
    ('铁观音', '青茶', '福建安溪', '300-1000米', 95, 45, 7, '["兰花香","果香","回甘"]'::jsonb, '铁观音既是茶名又是品种名，其名源自一个美丽的传说。清乾隆年间，安溪茶农魏荫每日以清茶敬奉观音菩萨。一夜梦见观音指引，在岩石间发现一株奇异的茶树，晨曦中方知是梦，但循梦所至，竟真见一株茶树在晨光中闪烁——叶片厚实如铁，重若观音，遂取名"铁观音"。铁观音独特的"观音韵"——一种介于花香与果香之间的缥缈韵味，让无数茶客为之倾倒。', '青茶代表，半发酵茶，兼具绿茶的清香和红茶的醇厚，"观音韵"妙不可言。', '#FFD700', '#DAA520', '#5C4033'),
    ('大红袍', '青茶', '福建武夷山', '600-1200米', 95, 40, 8, '["岩韵","果香","炭香"]'::jsonb, '大红袍为武夷岩茶之王，母树生长于武夷山天心岩九龙窠的绝壁之上，已有360余年历史。相传明洪武年间，一位进京赶考的举子途经武夷山，因腹痛难忍被天心寺僧人以岩茶治愈。举子高中状元后，将御赐红袍披于茶树之上以谢恩，"大红袍"由此得名。2005年，20克母树大红袍在拍卖会上拍出20.8万元天价，创造了茶叶拍卖的神话。', '武夷岩茶之王，条索紧结，色泽绿褐鲜润，"岩韵"明显，千年传奇。', '#E8B84A', '#C88A30', '#4A3D33'),
    ('武夷水仙', '青茶', '福建武夷山', '300-800米', 95, 40, 8, '["兰花香","粽叶香","醇厚"]'::jsonb, '水仙是武夷岩茶四大名丛之一，以"醇不过水仙"著称。武夷山水仙茶树多为百年以上老丛，根系深扎岩缝，吸收岩石中丰富的矿物质，形成了独特的"岩韵"。尤为珍贵的是"老枞水仙"——树龄超过六十年的老茶树，带有独特的"枞味"：青苔香、木质香、粽叶香层层叠叠，仿佛能品到时间的厚度。南宋陆游《建安雪》赞闽茶："建溪官茶天下绝，香味欲全须小雪。"', '岩茶当家品种，条索肥壮，香气幽雅，滋味醇厚，"醇不过水仙"名不虚传。', '#E8B84A', '#C88A30', '#4A3D33'),
    ('武夷肉桂', '青茶', '福建武夷山', '400-900米', 95, 35, 8, '["桂皮香","果香","岩韵"]'::jsonb, '肉桂原名"玉桂"，因香气似中药材肉桂而得名，是武夷岩茶的后起之秀。其香辛锐持久，有"香不过肉桂"之说。清代文人袁枚在《随园食单》中记载了他品武夷岩茶的体会："余向不喜武夷茶，嫌其浓苦如药。然丙午秋，余游武夷，到幔亭峰天游寺，僧道以茶献……始觉其清，再酌其香，终品其韵。"正是这段著名的品茶记录，让后人得以一窥清代岩茶品鉴之风韵。', '岩茶新贵，香气辛锐持久，滋味醇厚甘爽，"香不过肉桂"名不虚传。', '#F0C04A', '#C88A30', '#4A3D33'),
    ('铁罗汉', '青茶', '福建武夷山慧苑岩', '500-1000米', 100, 30, 9, '["药香","炭香","刚烈"]'::jsonb, '铁罗汉是武夷岩茶四大名丛之首，创制于宋代，已有千年历史。传说宋代高僧在慧苑岩修行时，见一株茶树形似罗汉，叶片在夕阳下泛着铁锈般的光泽。采制成茶后，汤色深红如铁，滋味刚烈醇厚，故名"铁罗汉"。北宋文学家范仲淹在《和章岷从事斗茶歌》中写道："武夷仙人从古栽"，说的就是武夷山这方水土与茶的千年因缘。', '四大名丛之首，创于宋代，茶性刚烈霸气，药香与炭香交融，千年传承。', '#D89A40', '#B07828', '#3D3025'),
    ('白鸡冠', '青茶', '福建武夷山火焰峰', '400-800米', 90, 40, 7, '["玉米香","清甜","柔美"]'::jsonb, '白鸡冠是武夷岩茶四大名丛中最具传奇色彩的一味，其嫩叶淡黄微白，形似鸡冠，故得此名。明代有一则动人的传说：武夷山中一白鸡修炼成精，化为女子与茶农相恋，被天庭贬回原形后，以身化为一株茶树，嫩叶永远保持着白色。白鸡冠一年只采一季春茶，产量极稀少，汤色淡金透亮，口感清甜柔美，在霸气十足的岩茶中独树一帜，被誉为"岩茶中的隐士"。', '四大名丛之一，叶色淡黄如鸡冠，汤色淡金，口感清甜柔美，岩茶中的"隐士"。', '#F0E8C0', '#C8B870', '#5A6E4A'),
    ('半天妖', '青茶', '福建武夷山三花峰', '600-1100米', 95, 35, 8, '["蜜香","果香","妖娆"]'::jsonb, '半天妖又名"半天鹞"，因茶树生长在武夷山三花峰半山腰的绝壁之上，如鹞鹰悬空，故得此名。清末茶学大家林馥泉编撰《武夷茶叶之生产制造及运销》时，将其列为武夷岩茶"十二金钗"之一。半天妖的香气变幻莫测，同一泡茶在不同的泡数中会展现出蜜香、果香、花香等多种面貌，令人捉摸不定，如妖似魅，故名"半天妖"。', '岩茶"十二金钗"之一，产自半山绝壁，香型变幻莫测，每一泡都有不同惊喜。', '#E8C04A', '#C8A030', '#4A3D33'),
    ('奇兰', '青茶', '福建武夷山', '400-900米', 90, 35, 7, '["兰花香","蜜香","清雅"]'::jsonb, '奇兰以其高扬的兰花香气闻名，是武夷岩茶中香型辨识度最高的品种之一。其名源自茶叶本身独特的兰花香韵。兰花自古被中国人视为"君子之花"，屈原在《离骚》中写道："余既滋兰之九畹兮，又树蕙之百亩。"以兰喻茶，寄托了文人对高洁品格的追求。奇兰性情温和，香气清雅不霸，是初次接触岩茶的绝佳选择。', '岩茶中香气辨识度最高的品种，兰花香高扬清雅，是入门岩茶的绝佳选择。', '#F0D8A0', '#C8A860', '#5A6E4A'),
    ('凤凰单丛', '青茶', '广东潮州', '800-1400米', 95, 25, 10, '["花香","蜜香","山韵"]'::jsonb, '凤凰单丛产自广东潮州凤凰山，因"单株采摘、单株制作"得名。潮汕工夫茶是中国茶道中最具仪式感的流派——"关公巡城、韩信点兵"的冲泡技法、三杯轮转的品饮礼仪，将茶道精神融入日常生活。凤凰单丛的品种香型多达上百种，是乌龙茶中香气最为丰富的品类。清代《潮州府志》记载："潮人嗜茶，无贵贱，晨夕必以茶佐食。"', '广东乌龙茶代表，香气高锐持久，品种香型上百种，有"茶中香水"之誉。', '#F0C84A', '#C8A030', '#5C4A3A'),
    ('冻顶乌龙', '青茶', '台湾南投', '600-1000米', 90, 40, 6, '["桂花香","果香","回甘"]'::jsonb, '冻顶乌龙产自台湾南投县鹿谷乡冻顶山，是台湾最具代表性的乌龙茶。相传清道光年间，林凤池赴福建应试，带回武夷山茶苗36株，其中12株种植于冻顶山，开启了台湾乌龙茶的传奇。冻顶山终年云雾缭绕、气温较低，茶树生长缓慢，茶叶质地尤为细嫩，冲泡后茶汤金黄明亮，桂花香气优雅迷人。台湾茶界有"北包种，南冻顶"之说，足见其地位。', '台湾最具代表性的乌龙茶，茶汤金黄明亮，桂花香气优雅。', '#F0C850', '#C8A038', '#5C4A3A'),
    ('金骏眉', '红茶', '福建武夷山', '1000-1500米', 90, 50, 6, '["蜜香","薯香","甘甜"]'::jsonb, '金骏眉创制于2005年，是中国红茶史上最年轻的传奇。它由武夷山桐木关的茶农在正山小种传统工艺基础上创新改良而成——只取春季单芽，每500克金骏眉需6-8万颗芽尖，一位熟练采茶工一天只能采不到一斤。金骏眉一问世便轰动茶界，被誉为"红茶中的爱马仕"。其名寓意深远："金"喻其金贵的品质，"骏"取"骏马奔腾"之意喻其发展之势，"眉"指茶叶如眉般细嫩。', '正山小种的顶级创新品种，金黄色的茶芽，蜜香浓郁，红茶新贵。', '#FFB347', '#CD853F', '#8B4513'),
    ('正山小种', '红茶', '福建武夷山', '800-1400米', 90, 60, 5, '["松烟香","桂圆香","甘甜"]'::jsonb, '正山小种是世界红茶的鼻祖，创制于明代中后期（约1568年）。相传一次军队路过武夷山桐木关，驻扎在茶厂中，铺在竹席上的待制茶叶被军队当床铺使用。茶农回来后，为挽回损失将茶叶经松烟熏焙，意外创造出了一种前所未有、带有独特松烟香的红茶。17世纪，正山小种通过荷兰东印度公司传入欧洲，迅速风靡英国皇室——英国下午茶文化由此发端。', '世界红茶始祖，条索肥实，色泽乌润，独特的松烟香穿越四百年。', '#E8A040', '#B87030', '#3D2B1F'),
    ('滇红', '红茶', '云南凤庆', '1000-1800米', 90, 45, 5, '["蜜香","果香","醇厚"]'::jsonb, '滇红创制于1939年，正值抗日战争最艰难的时期。中国茶叶公司在云南凤庆设立茶厂，以云南大叶种茶为原料试制红茶，成功创制出金毫显露、滋味醇厚的"滇红"。滇红一出世即通过香港转运出口，换取军需物资，为抗战做出了特殊贡献。云南大叶种茶树树高可达数丈，叶大如掌，茶多酚含量远超小叶种，因此滇红尤其浓郁耐泡，被称为"红茶中的硬汉"。', '云南红茶代表，条索肥硕紧实，金毫特显，汤色红艳明亮，红茶中的硬汉。', '#E86040', '#B84020', '#4A3020'),
    ('祁门红茶', '红茶', '安徽祁门', '300-800米', 90, 55, 5, '["兰花香","蜜糖香","祁门香"]'::jsonb, '祁门红茶是世界三大高香红茶之一（与大吉岭、锡兰红茶并列），以独特的"祁门香"闻名于世。1875年，祁门人胡元龙借鉴福建红茶工艺试制祁红成功，从此改写了中国红茶的历史。1915年，祁门红茶在巴拿马万国博览会上一举夺得金质奖章。英国茶界将这种不可复制的复合香气命名为"祁门香"——似花似蜜似果，被誉为"王子之香"。唐代白居易《琵琶行》"商人重利轻别离，前月浮梁买茶去"中的浮梁，即今江西景德镇浮梁县，与安徽祁门山水相邻，自古便是皖赣边境茶叶集散重镇。', '中国十大名茶之一，世界三大高香红茶之一，以"祁门香"香醉世界。', '#E86040', '#B84020', '#3D2B1F'),
    ('老班章普洱', '黑茶', '云南勐海', '1200-1800米', 100, 30, 15, '["陈香","木质香","回甘"]'::jsonb, '老班章被誉为"普洱之王"，产自西双版纳勐海县布朗山老班章村。村中古茶树多为300-500年树龄，根系深达数丈，吸收了原始森林中丰富的矿物质。"班章为王，易武为后"——普洱茶界流传着这样的说法。老班章的茶气之刚烈在普洱茶中无出其右，初饮如烈酒入喉，随即化为满口回甘，经久不散。普洱茶的"越陈越香"正体现了东方文化中"藏"的智慧——懂得等待，方得真味。', '普洱茶中的王者，条索肥壮，茶气刚烈，回甘持久，越陈越香。', '#8B4513', '#654321', '#3D2B1F'),
    ('六堡茶', '黑茶', '广西梧州', '200-600米', 100, 40, 12, '["陈香","槟榔香","醇滑"]'::jsonb, '六堡茶原产广西苍梧县六堡镇，清代以来远销东南亚，是著名的"侨销茶"。19世纪下南洋的华工们从家乡出发时，行囊中总少不了几块六堡茶，它既能解暑祛湿，又能慰藉乡愁——"一杯六堡，千里故乡"。六堡茶独特的"槟榔香"是茶叶陈化过程中自然形成的，不拼配任何香料，但其香气却与槟榔惊人相似，堪称大自然的鬼斧神工。', '广西黑茶代表，条索紧结，汤色红浓明亮，以"红、浓、陈、醇"著称。', '#B84A30', '#8A3020', '#3D2B1F'),
    ('安化黑茶', '黑茶', '湖南安化', '300-800米', 100, 35, 10, '["菌花香","醇和","甘甜"]'::jsonb, '安化是中国黑茶之乡，其产茶历史可追溯至唐代。安化最负盛名的"千两茶"被列为国家级非物质文化遗产，每卷茶重约36.25公斤（合老秤一千两），需由数名壮汉踩制数小时方能成型。宋神宗熙宁年间，安化黑茶被纳入"茶马互市"体系——中原以茶换边疆之马，成为维系汉藏经济命脉的重要纽带。明清时期，晋商开辟"万里茶路"，安化黑茶沿此路远销俄罗斯圣彼得堡。', '湖南黑茶代表，历史悠久，千两茶为非遗，茶马古道的重要见证。', '#C86A40', '#9A4A28', '#3D3025'),
    ('茯砖茶', '黑茶', '陕西咸阳', '500-1000米', 100, 30, 10, '["菌花香","醇和","甘滑"]'::jsonb, '茯砖茶以其独特的"金花"（冠突散囊菌）闻名，茶砖内部满布金黄色颗粒，在显微镜下如繁花绽放。茯砖茶原产于陕西泾阳，历史上是"茶马古道"上西北少数民族的生活必需品——"宁可三日无粮，不可一日无茶"。茯砖茶中的"金花"是一种有益益生菌，能促进消化、降脂解腻。自古就有"一日无茶则滞，三日无茶则病"的民谚。', '陕西黑茶代表，茶砖内满布金黄色"金花"，滋味醇厚甘滑，西北民族的生命之茶。', '#C86A40', '#9A4A28', '#3D3025'),
    ('安吉白茶', '绿茶', '浙江安吉', '500-1000米', 80, 45, 3, '["鲜爽","甘甜","滑润"]'::jsonb, '安吉白茶是珍稀白化品种（白叶一号），按绿茶工艺制作，氨基酸含量为普通绿茶3倍，滋味格外鲜爽。', '白化品种绿茶，氨基酸含量突出。', '#F0F5E8', '#B8C9A8', '#7BA87A'),
    ('六安瓜片', '绿茶', '安徽六安', '400-800米', 80, 45, 3, '["栗香","鲜爽","醇厚"]'::jsonb, '中国唯一无芽无梗绿茶，由单片叶制成。清代为贡茶，周恩来总理生前最爱。', '唯一无芽无梗绿茶，单片叶制作。', '#E8F5E0', '#A8C99A', '#6B9E5A'),
    ('蒙顶甘露', '绿茶', '四川雅安', '800-1400米', 80, 50, 3, '["嫩香","鲜爽","回甘"]'::jsonb, '蒙顶山是中国茶文化发源地，公元前53年吴理真在此种茶，被尊为"茶祖"。', '最古老名茶，茶祖吴理真手植。', '#F0F5E8', '#B8C9A8', '#5B8C5A'),
    ('恩施玉露', '绿茶', '湖北恩施', '500-1200米', 75, 40, 3, '["海苔香","鲜爽","清甜"]'::jsonb, '中国唯一保留下来的蒸青绿茶工艺，源自唐代。恩施是中国最大富硒茶产区。', '中国唯一蒸青绿茶，唐代工艺活化石。', '#E8F5E0', '#A8C99A', '#6B9E5A'),
    ('婺源绿茶', '绿茶', '江西婺源', '300-1000米', 80, 50, 3, '["清香","鲜爽","醇和"]'::jsonb, '婺源是中国最美乡村之一，以"叶绿、汤清、香高、味醇"四绝著称。', '江南绿茶代表，四绝名扬。', '#E8F5E0', '#A8C99A', '#6B9E5A'),
    ('庐山云雾', '绿茶', '江西九江', '500-1200米', 80, 50, 3, '["豆香","鲜爽","甘甜"]'::jsonb, '庐山云雾为中国十大名茶之一，庐山为佛教名山，僧人种茶历史悠久。', '十大名茶，庐山僧人千年传承。', '#F0F5E8', '#B8C9A8', '#5B8C5A'),
    ('狮峰龙井', '绿茶', '浙江杭州', '50-400米', 80, 60, 3, '["豆香","栗香","鲜爽"]'::jsonb, '狮峰山是龙井品质最好的核心产区，乾隆御封十八棵御茶所在。', '龙井之巅，乾隆御茶核心产区。', '#F5E6A3', '#C9B458', '#4A7C59'),
    ('顾渚紫笋', '绿茶', '浙江长兴', '200-500米', 80, 50, 3, '["兰花香","鲜爽","甘醇"]'::jsonb, '唐代第一贡茶，陆羽《茶经》多次提及。设贡茶院为历史上最早皇家茶厂。', '唐代第一贡茶，最早皇家茶厂。', '#F0F5E8', '#B8C9A8', '#5B8C5A'),
    ('寿眉', '白茶', '福建福鼎', '400-1000米', 95, 120, 7, '["枣香","药香","醇和"]'::jsonb, '寿眉"一年茶、三年药、七年宝"。传统白茶工艺，自然萎凋。', '白茶经典，越陈越香。', '#F5F0D8', '#D4C89A', '#9AAD8A'),
    ('政和白毫银针', '白茶', '福建政和', '600-1200米', 85, 120, 5, '["毫香","清甜","醇厚"]'::jsonb, '政和白茶茶味醇厚，与福鼎白茶清雅对比鲜明。政和大白茶品种独特。', '白茶中茶味最醇厚者。', '#F5F0D8', '#D4C89A', '#9AAD8A'),
    ('洞庭碧螺春（传统）', '绿茶', '江苏苏州', '100-300米', 75, 45, 3, '["花果香","清甜","鲜嫩"]'::jsonb, '正宗洞庭碧螺春产自太湖东山，茶树与果树间作，天然花果香。', '正宗洞庭山产区，茶果间作花果香。', '#E8F5E9', '#A5D6A7', '#6B8E23'),
    ('阳羡雪芽', '绿茶', '江苏宜兴', '200-500米', 80, 45, 3, '["清香","鲜爽","甘甜"]'::jsonb, '阳羡茶唐代即为贡茶，卢仝"天子须尝阳羡茶，百草不敢先开花"即赞此茶。', '唐代贡茶，卢仝盛赞。', '#E8F5E0', '#A8C99A', '#6B9E5A'),
    ('阿里山乌龙', '青茶', '台湾嘉义', '1000-1600米', 90, 40, 6, '["花香","果香","清雅"]'::jsonb, '阿里山全球海拔最高茶区之一，独特"高山韵"，茶汤清亮。', '全球最高海拔茶区，独特高山韵。', '#F0C850', '#C8A038', '#5C4A3A'),
    ('文山包种', '青茶', '台湾台北', '300-700米', 85, 35, 5, '["花香","清雅","甘甜"]'::jsonb, '台湾发酵最轻的乌龙茶，香气清雅有"露凝香"之称。', '台湾最轻发酵乌龙，"露凝香"。', '#F0E8C0', '#C8B870', '#5A6E4A'),
    ('英德红茶', '红茶', '广东英德', '200-500米', 90, 45, 5, '["蜜香","果香","醇厚"]'::jsonb, '英德红茶创制于1959年，被誉为"中国红茶后起之秀"。', '广东红茶代表，后起之秀。', '#E86040', '#B84020', '#4A3020'),
    ('宁红工夫', '红茶', '江西修水', '300-800米', 90, 50, 5, '["蜜香","甜润","醇和"]'::jsonb, '宁红是中国最早工夫红茶之一，清代出口欧美。黄庭坚故里茶文化深厚。', '最早工夫红茶，出口欧美百年。', '#E86040', '#B84020', '#4A3020'),
    ('川红工夫', '红茶', '四川宜宾', '300-1000米', 90, 45, 5, '["橘糖香","甜醇","鲜爽"]'::jsonb, '川红以宜宾紫土孕育，独特橘糖香，以"早、嫩、香"著称。', '四川红茶代表，紫土橘糖香。', '#E86040', '#B84020', '#4A3020'),
    ('生普洱（景迈）', '黑茶', '云南普洱', '1000-1800米', 95, 20, 15, '["花香","山野韵","甘甜"]'::jsonb, '景迈山千年古茶林为世界文化遗产。生普陈放后自然转化，越陈越香。', '世界文化遗产景迈山，自然陈化。', '#8B4513', '#654321', '#3D2B1F'),
    ('熟普洱（景迈）', '黑茶', '云南普洱', '1000-1800米', 100, 25, 15, '["陈香","枣香","醇滑"]'::jsonb, '景迈古树熟普渥堆发酵精制，汤色红浓，口感醇滑。', '古树熟普，红浓醇滑。', '#8B4513', '#654321', '#3D2B1F'),
    ('陈皮普洱', '黑茶', '广东新会', '200-1500米', 100, 30, 12, '["陈皮香","陈香","甘醇"]'::jsonb, '陈皮普洱以新会陈皮搭配云南普洱，茶与果的完美结合。', '陈皮与普洱的完美融合。', '#C86A40', '#9A4A28', '#3D3025'),
    ('云南古树晒红', '红茶', '云南临沧', '1200-2000米', 90, 50, 6, '["蜜香","果香","甜润"]'::jsonb, '晒红以古树茶为原料，日光干燥替代烘干，可长期陈放。', '古树日晒，可长期陈放的红茶。', '#E86040', '#B84020', '#4A3020'),
    ('云南普洱散茶', '黑茶', '云南西双版纳', '800-1500米', 100, 30, 12, '["陈香","醇和","甘滑"]'::jsonb, '普洱茶自古以来就是茶马古道的灵魂，千年茶文化见证者。', '茶马古道千年灵魂。', '#8B4513', '#654321', '#3D2B1F'),
    ('景迈山普洱', '黑茶', '云南普洱', '1000-1800米', 100, 25, 15, '["蜜香","山野韵","醇和"]'::jsonb, '景迈山是世界文化遗产，千年万亩古茶林中最古老的一片。', '世界文化遗产，千年古茶林。', '#8B4513', '#654321', '#3D2B1F'),
    ('横县茉莉花茶', '绿茶', '广西南宁横州', '100-300米', 85, 45, 4, '["茉莉花香","鲜灵","甘甜"]'::jsonb, '横县是"中国茉莉之乡"、中国最大茉莉花茶产区，以绿茶茶坯经多次窨制，花香茶韵交融。', '中国茉莉之乡，窨制工艺精湛，花香茶韵交融。', '#F0F5E8', '#B8C9A8', '#5B8C5A'),
    ('白沙绿茶', '绿茶', '海南白沙', '100-400米', 80, 50, 3, '["清鲜","甘甜","豆香"]'::jsonb, '白沙绿茶产于白沙陨石坑周边，土壤富含矿物质，为中国国家地理标志产品。', '陨石坑土壤孕育，矿物质丰富。', '#E8F5E0', '#A8C99A', '#6B9E5A'),
    ('五指山红茶', '红茶', '海南五指山', '600-1200米', 90, 45, 4, '["蜜香","浓郁","甜润"]'::jsonb, '五指山高山云雾茶，蜜香浓郁，2015年获国家农产品地理标志登记。', '高山云雾红茶，蜜香浓郁。', '#E86040', '#B84020', '#4A3020'),
    ('东方美人', '青茶', '台湾新竹北埔', '300-800米', 85, 40, 6, '["蜜香","果香","醇和"]'::jsonb, '又称"白毫乌龙""香槟乌龙"，茶青需经小绿叶蝉叮咬，英国维多利亚女王品尝后赐名"东方美人"。', '小绿叶蝉叮咬后采制，蜜香馥郁，维多利亚女王赐名。', '#F0C850', '#C8A038', '#5C4A3A'),
    ('日月潭红茶', '红茶', '台湾南投鱼池', '600-1000米', 90, 40, 4, '["薄荷香","肉桂香","醇厚"]'::jsonb, '日据时期从印度引入阿萨姆种，台茶18号"红玉"具独特薄荷肉桂香。', '阿萨姆种，台茶18号红玉薄荷肉桂香。', '#E86040', '#B84020', '#4A3020'),
    ('普洱茶', '黑茶', '云南西双版纳、普洱、临沧', '800-1800米', 100, 30, 15, '["陈香","醇厚","回甘"]'::jsonb, '以云南大叶种晒青毛茶为原料，分生茶（自然陈化）与熟茶（人工渥堆发酵），"越陈越香"。', '云南大叶种晒青毛茶，生熟两制，越陈越香。', '#8B4513', '#654321', '#3D2B1F'),
    ('都匀毛尖', '绿茶', '贵州黔南都匀', '800-1300米', 80, 45, 3, '["栗香","鲜爽","回甘"]'::jsonb, '以"三绿三黄"（干茶绿中带黄、汤色绿中透黄、叶底绿中显黄）著称，1915年获巴拿马万国博览会奖。', '"三绿三黄"，1915年巴拿马万国博览会获奖。', '#E8F5E0', '#A8C99A', '#6B9E5A'),
    ('湄潭翠芽', '绿茶', '贵州遵义湄潭', '600-1200米', 80, 50, 3, '["栗香","清鲜","甘醇"]'::jsonb, '扁平光滑、形似葵花籽，栗香持久，产自"中国名茶之乡"湄潭。', '扁平似葵花籽，栗香持久，名茶之乡湄潭。', '#E8F5E0', '#A8C99A', '#6B9E5A'),
    ('竹叶青', '绿茶', '四川乐山峨眉山', '800-1500米', 80, 50, 3, '["嫩栗香","鲜爽","清甜"]'::jsonb, '扁平挺直似竹叶，1964年陈毅元帅命名，开创"论道""静心"等高端系列。', '扁平挺直似竹叶，陈毅元帅命名。', '#F0F5E8', '#B8C9A8', '#5B8C5A'),
    ('易贡茶', '绿茶', '西藏林芝易贡', '2200-2500米', 80, 45, 3, '["清香","鲜爽","醇和"]'::jsonb, '产于海拔2200-2500米易贡茶场，是世界海拔最高的有机茶场之一，1960年兵团援建。', '世界海拔最高有机茶场之一。', '#E8F5E0', '#A8C99A', '#6B9E5A'),
    ('南京雨花茶', '绿茶', '江苏南京', '50-300米', 80, 45, 3, '["清香","鲜爽","甘醇"]'::jsonb, '1958年创制，形似松针，象征革命先烈坚贞不屈，中国十大名茶之一。', '形似松针，1958年创制，中国十大名茶。', '#E8F5E0', '#A8C99A', '#6B9E5A'),
    ('宜昌红茶', '红茶', '湖北宜昌', '200-800米', 90, 45, 5, '["蜜香","甜醇","鲜爽"]'::jsonb, '"宜红"与祁红、滇红并称中国三大工夫红茶，19世纪中叶出口欧洲，是"万里茶道"重要商品。', '三大工夫红茶之一，万里茶道重要商品。', '#E86040', '#B84020', '#4A3020'),
    ('紫阳富硒茶', '绿茶', '陕西安康紫阳', '400-1200米', 80, 50, 3, '["栗香","鲜爽","回甘"]'::jsonb, '中国唯一通过科学鉴定的富硒茶产区，土壤天然含硒，唐代已为贡品。', '中国唯一科学鉴定富硒茶产区，唐代贡品。', '#F0F5E8', '#B8C9A8', '#5B8C5A'),
    ('汉中仙毫', '绿茶', '陕西汉中', '500-1500米', 80, 50, 3, '["栗香","鲜爽","甘甜"]'::jsonb, '整合"午子仙毫""定军茗眉""宁强雀舌"等品牌，高山云雾茶，国家地理标志产品。', '高山云雾茶，国家地理标志产品。', '#E8F5E0', '#A8C99A', '#6B9E5A'),
    ('陇南绿茶', '绿茶', '甘肃陇南文县、武都、康县', '600-1200米', 80, 50, 3, '["清香","鲜爽","醇厚"]'::jsonb, '甘肃唯一产茶区，海拔600-1200米高山云雾茶，内含物质丰富。', '甘肃唯一产茶区，高山云雾内含物丰富。', '#E8F5E0', '#A8C99A', '#6B9E5A'),
    ('日照绿茶', '绿茶', '山东日照', '100-500米', 85, 45, 3, '["栗香","浓郁","耐泡"]'::jsonb, '1966年"南茶北引"成功，中国纬度最高茶区之一，昼夜温差大，栗香浓郁耐冲泡。', '南茶北引成功，纬度最高茶区之一。', '#F0F5E8', '#B8C9A8', '#5B8C5A'),
    ('崂山绿茶', '绿茶', '山东青岛崂山', '100-600米', 85, 45, 3, '["豌豆香","清鲜","甘甜"]'::jsonb, '1958年"南茶北引"，崂山矿泉水灌溉，"豌豆香"独特，国家地理标志产品。', '崂山矿泉水灌溉，豌豆香独特。', '#E8F5E0', '#A8C99A', '#6B9E5A');
INSERT INTO tea_people (name, dynasty, title, avatar, description, contribution, quote, related_tea_ids) VALUES
    ('陆羽', '唐', '茶圣', 'ScrollText', '陆羽（733-804），字鸿渐，唐代复州竟陵人。著有世界上第一部茶叶专著《茶经》，开中国茶道之先河，被后世尊为"茶圣"。', '撰《茶经》三卷十篇，系统论述茶的起源、品种、采制、烹煮、器具、水质、饮用等，奠定了中国茶文化的理论基础。', '茶者，南方之嘉木也。其树如瓜芦，叶如栀子，花如白蔷薇，实如栟榈，蒂如丁香，根如胡桃。', '["longjing","biluochun"]'::jsonb),
    ('苏轼', '宋', '茶中诗仙', 'Leaf', '苏轼（1037-1101），号东坡居士，北宋文豪。一生爱茶，写下近百首茶诗，其"且将新火试新茶"传诵千古。', '以诗文传茶道，提出"活水还须活火烹"的烹茶理念，对宋代点茶文化有深远影响。', '且将新火试新茶，诗酒趁年华。', '["longjing","tieguanyin"]'::jsonb),
    ('赵佶', '宋', '皇帝茶人', 'Crown', '宋徽宗赵佶（1082-1135），北宋第八位皇帝。亲撰《大观茶论》，是中国历史上唯一一位为茶著书立说的帝王。', '著《大观茶论》二十篇，详述宋代点茶技艺，提出"清、和、淡、洁"的品茶精神，将茶道提升至哲学高度。', '至若茶之为物，擅瓯闽之秀气，钟山川之灵禀，祛襟涤滞，致清导和。', '["baihaoyinzhen","baimudan"]'::jsonb),
    ('乾隆', '清', '六下江南品茶帝', 'Landmark', '爱新觉罗·弘历（1711-1799），清乾隆帝。六下江南、四次驾临龙井茶区，亲封狮峰十八棵茶树为"御茶"；一生御制茶诗数百首，嗜茶成癖。', '推动龙井茶名扬天下，题诗《观采茶作歌》；御制茶诗数百首，对茶文化的传播做出不可磨灭的贡献。', '火前嫩，火后老，惟有骑火品最好。', '["longjing","biluochun"]'::jsonb),
    ('袁枚', '清', '随园茶客', 'PenLine', '袁枚（1716-1797），清代诗人、美食家。著《随园食单》，其中"茶酒单"一章记录了清代品茶之风的精髓。', '《随园食单》中详细记载了武夷岩茶、龙井、六安等茶的品饮心得，提出"始觉其清，再酌其香，终品其韵"的品茶三境界。', '余向不喜武夷茶，嫌其浓苦如药。然丙午秋，始觉其清，再酌其香，终品其韵。', '["dahongpao","shuixian","rougui"]'::jsonb),
    ('陆游', '宋', '茶诗第一', 'FileText', '陆游（1125-1210），南宋诗人。一生创作三百余首茶诗，是中国历史上写茶诗最多的诗人。', '以三百余首茶诗记录了南宋时期的茶事活动，为后世研究宋代茶文化提供了珍贵史料。', '建溪官茶天下绝，香味欲全须小雪。', '["shuixian","dahongpao","tieluohan"]'::jsonb),
    ('白居易', '唐', '茶中隐士', 'Sunrise', '白居易（772-846），唐代诗人。晚年号香山居士，嗜茶如命，在《琵琶行》等名篇中多次提及茶事。', '以诗记茶，在《琵琶行》中"商人重利轻别离，前月浮梁买茶去"记录了唐代茶叶贸易的繁荣景象。', '坐酌泠泠水，看煎瑟瑟尘。无由持一碗，寄与爱茶人。', '["qimenhong","lapsangsouchong"]'::jsonb),
    ('张又新', '唐', '煎茶水记', 'Droplet', '张又新，唐代学者。著《煎茶水记》，是中国最早系统评水的专著，对后世茶道中的"水为茶之母"理念影响深远。', '撰《煎茶水记》，将天下水分为七等：镇江中泠泉第一、无锡惠山泉第二、虎跑泉第三……为品水论泉之祖。', '夫茶烹于所产处，无不佳也，盖水土之宜。离其处，水功其半，然善烹洁器，全其功也。', '["longjing","biluochun"]'::jsonb),
    ('朱权', '明', '茶道创新者', 'BookOpen', '朱权（1378-1448），明太祖朱元璋第十七子，宁献王。著《茶谱》，开明代瀹茶（散茶冲泡）之先河。', '撰《茶谱》，提出"瀹饮法"——改宋代点茶为散茶直接冲泡，奠定了现代泡茶方式的基础。', '茶之为物，可以助诗兴而云山顿色，可以伏睡魔而天地忘形。', '["longjing","biluochun"]'::jsonb),
    ('许次纾', '明', '茶疏作者', 'ScrollText', '许次纾（1549-1604），明代茶学家。著《茶疏》，是明代最杰出的茶学著作之一。', '撰《茶疏》，提出"产茶、采茶、制茶、藏茶、烹茶、品茶"的系统理论，对明代茶文化贡献卓越。', '茶滋于水，水藉乎器，汤成于火。四者相须，缺一则废。', '["longjing","tieguanyin"]'::jsonb),
    ('文震亨', '明', '长物志作者', 'TreePine', '文震亨（1585-1645），明代文人、造园家。著《长物志》，其中"茶寮"一卷详述明代文人茶空间布置。', '在《长物志》中提出"茶寮"概念——专设一间茶室用于品茶，对后世日本茶道"茶室"产生了深远影响。', '构一斗室，相傍山斋，内设茶具，教一童专主茶役，以供长日清谈，寒宵兀坐。幽人首务，不可少废者。', '["shuixian","dahongpao"]'::jsonb),
    ('吴觉农', '现代', '当代茶圣', 'Landmark', '吴觉农（1897-1988），中国现代茶学奠基人，被誉为"当代茶圣"。', '创建中国第一个茶叶研究所、第一所茶叶学校，主编《茶经述评》，为中国茶产业现代化做出卓越贡献。', '中国茶业如睡狮一般，一朝醒来，决不会长落人后，愿大家努力罢！', '["longjing","qimenhong"]'::jsonb),
    ('欧阳修', '宋', '文忠公茶客', 'BookOpen', '欧阳修（1007-1072），北宋文坛领袖。一生爱茶，在《归田录》中记载了宋代茶事。', '在《归田录》中详记宋代贡茶制度，提出"茶之品无有贵于龙凤者"的著名论断。', '吾年向老世味薄，所好未衰惟饮茶。', '["longjing"]'::jsonb),
    ('李清照', '宋', '茶中词后', 'Flower', '李清照（1084-1155），宋代女词人。以"赌书泼茶"的典故为茶文化增添了一抹浪漫色彩。', '"赌书泼茶"的典故成为文人茶事的经典意象——与丈夫赵明诚以茶赌书，欢乐洋溢。', '酒阑更喜团茶苦，梦断偏宜瑞脑香。', '["baimudan"]'::jsonb),
    ('范成大', '宋', '石湖茶隐', 'Mountain', '范成大（1126-1193），南宋诗人。晚年隐居石湖，以茶为伴，写有多首茶诗。', '在《吴郡志》中记载了宋代苏州茶事，为研究宋代茶史提供了珍贵资料。', '胡蝶双双入菜花，日长无客到田家。鸡飞过篱犬吠窦，知有行商来买茶。', '["biluochun"]'::jsonb),
    ('杨万里', '宋', '诚斋茶客', 'Leaf', '杨万里（1127-1206），南宋诗人。一生作诗两万余首，其中茶诗数十首。', '以清新自然的笔触描写日常饮茶，将茶融入生活的每一处细节。', '鹰爪新茶蟹眼汤，松风鸣雪兔毫霜。', '["longjing"]'::jsonb),
    ('徐渭', '明', '青藤茶客', 'Palette', '徐渭（1521-1593），明代文人、书画家。一生坎坷，寄情于茶与书画。', '在《煎茶七类》中提出"人品、品水、烹点、尝茶、茶宜、茶侣、茶勋"七个品茶维度。', '茶宜精舍，宜云林，宜瓷瓶，宜竹灶。', '["tieguanyin"]'::jsonb),
    ('张岱', '明末清初', '陶庵茶痴', 'Landmark', '张岱（1597-1679），明末清初文学家、史学家。精于品茶，自称"茶痴"。', '在《陶庵梦忆》中记载了明代末年江南茶事的繁华景象，是研究明代茶文化的珍贵史料。', '慕汶老久，今日不畅饮汶老茶，决不去。', '["longjing","biluochun"]'::jsonb),
    ('金农', '清', '冬心茶禅', 'Paintbrush', '金农（1687-1763），清代画家，扬州八怪之首。嗜茶如命，画中常以茶入题。', '将茶与文人画结合，创作了大量以茶为主题的绘画作品，诗画相映成趣。', '草铺绿罽地无尘，朝日熹微榆火新。两串春团三道印，不知茶宴赴何人。', '["shuixian","dahongpao"]'::jsonb),
    ('蒲松龄', '清', '聊斋茶叟', 'BookOpen', '蒲松龄（1640-1715），清代文学家。在路边设茶摊，以茶换故事，终成《聊斋志异》。', '以茶换故事的创作方式成为中国文学史上的佳话，体现了茶在民间文化中的独特作用。', '途中设茶茗，邀行人小憩，与谈狐鬼。', '["lapsangsouchong"]'::jsonb),
    ('曹雪芹', '清', '红楼茶隐', 'ScrollText', '曹雪芹（1715-1763），清代文学家，《红楼梦》作者。在书中描写了大量品茶场景。', '《红楼梦》中涉及茶事多达260余处，"栊翠庵品茶"一回为中国文学中最精彩的茶事描写。', '一杯为品，二杯即是解渴的蠢物，三杯便是饮牛饮骡了。', '["longjing","qimenhong"]'::jsonb);
INSERT INTO tea_poems (title, author, dynasty, content, related_tea_ids, description) VALUES
    ('望江南·超然台作', '苏轼', '宋', '春未老，风细柳斜斜。试上超然台上看，半壕春水一城花。烟雨暗千家。
INSERT INTO teawares (name, ware_type, material, capacity, description, culture_story, bonus, recommended, rarity) VALUES
    ('白瓷盖碗', '盖碗', '白瓷（釉面）', 150, '瓷器釉面光滑不吸味，薄壁散热适中，出汤速度可控。适合冲泡大多数茶类，尤其高香细嫩茶。', '盖碗始于明代，又称"三才碗"——盖为天、托为地、碗为人。鲁迅在《喝茶》中写道："喝好茶，是要用盖碗的。"', '{"speed":1.2,"heatRetention":0.8,"visual":1}'::jsonb, '["绿茶","白茶","青茶","黄茶"]'::jsonb, 'common'),
    ('紫砂壶', '紫砂壶', '宜兴紫砂（双气孔，无釉）', 150, '紫砂双气孔结构保温性极佳，会吸附茶味形成"茶山"（建议一壶一茶）。适合普洱、红茶、焙火乌龙。', '紫砂壶产于江苏宜兴，明代供春创制。其"透气不透水"的独特结构，使其成为茶道至宝。', '{"speed":0.8,"heatRetention":1.3,"visual":0.6}'::jsonb, '["黑茶","红茶","青茶"]'::jsonb, 'common'),
    ('玻璃杯', '玻璃杯', '高硼硅玻璃', 300, '玻璃完全无孔不吸味、导热快散热最快。透明度高，可全程欣赏茶叶舒展与"茶舞"，视觉体验最佳。', '玻璃茶具虽不如瓷器紫砂历史悠久，但现代高硼硅玻璃的耐热性能使其成为观赏绿茶茶舞的理想之选。', '{"speed":1,"heatRetention":0.6,"visual":1.4}'::jsonb, '["绿茶","白茶","黄茶"]'::jsonb, 'common'),
    ('青瓷盖碗', '盖碗', '龙泉青瓷（釉面）', 130, '龙泉青瓷以"青如玉、明如镜、声如磬"著称。釉色温润，与绿茶茶汤相映成趣，视觉享受极佳。', '龙泉青瓷始于三国，盛于南宋。弟窑白胎厚釉、哥窑紫口铁足，各具风韵。', '{"speed":1.1,"heatRetention":0.9,"visual":1.3}'::jsonb, '["绿茶","白茶","黄茶"]'::jsonb, 'uncommon'),
    ('段泥石瓢壶', '紫砂壶', '宜兴段泥（紫砂）', 180, '段泥紫砂色泽米黄，砂质感强。石瓢造型稳重大方，壶口宽大便于投放条索型茶叶。', '石瓢壶为紫砂经典器型之一，源自清代陈曼生设计的"曼生十八式"，一改紫砂繁复之风，开文人壶先河。', '{"speed":0.9,"heatRetention":1.1,"visual":0.9}'::jsonb, '["青茶","红茶","黑茶"]'::jsonb, 'uncommon'),
    ('建盏天目杯', '盖碗', '建阳铁胎（黑釉）', 80, '建盏为宋代点茶神器，铁胎厚实保温极佳。兔毫/油滴釉面在茶汤映照下流光溢彩，极具观赏性。', '建盏产自福建建阳，宋代点茶之风最尚黑釉盏，宋徽宗《宫词》咏道："兔毫连盏烹云液，能解红颜入醉乡。"', '{"speed":0.7,"heatRetention":1.4,"visual":1.2}'::jsonb, '["黑茶","红茶"]'::jsonb, 'rare');
INSERT INTO tea_etiquettes (name, occasion, description, steps) VALUES
    ('客来敬茶', '日常待客', '"客来敬茶"是中国最基本的茶礼，也是中华民族的传统美德。无论贫富，客至必奉茶，表达了主人对客人的尊重与欢迎。', '["净手洁器：泡茶前洗净双手，温烫茶具","投茶入壶：取适量茶叶放入茶壶或盖碗","注水冲泡：用适宜温度的水冲泡","静候片刻：等待茶叶舒展、茶汤析出","双手奉茶：用双手端杯，茶杯置于茶托上，恭敬奉于客人面前","请茶示意：以手势示意\"请用茶\"","续茶添暖：客人杯中茶剩三分之一时及时续水"]'::jsonb),
    ('工夫茶礼', '潮汕工夫茶', '潮汕工夫茶是中国茶道中最具仪式感的流派，讲究"和、敬、精、洁"四字真谛。', '["列器备茶：排列茶具，准备茶叶","温壶烫杯：用开水烫洗茶壶和茶杯","纳茶：将茶叶纳入茶壶，约占茶壶七分满","醒茶：注水后迅速倒出，唤醒茶香","冲泡：沿壶口环壁注水","刮沫：用壶盖刮去表面泡沫","淋壶：用开水淋浇壶身，提升温度","烫杯：用温杯的热水依次烫洗品茗杯","出汤：按\"关公巡城\"依次巡回注入各杯","点茶：最后几滴按\"韩信点兵\"均匀分入各杯","奉茶：双手奉于客人面前","品茶：先闻香，再品味，三口饮尽"]'::jsonb),
    ('宋代点茶礼', '点茶雅集', '宋代是中国茶文化的巅峰时期，点茶法是宋人饮茶的主要方式。宋徽宗《大观茶论》将点茶技艺推向极致。', '["炙茶：用微火炙烤茶饼，激发香气","碾茶：将茶饼碾碎成细末","罗茶：用细罗筛滤茶末，确保细腻均匀","烘盏：用热水温热茶盏","调膏：将少量热水注入茶末，调成膏状","注水点茶：用执壶向茶盏中注水，同时用茶筅击拂","击拂：用茶筅在茶汤中来回击打，产生细腻泡沫","鉴赏：观看茶汤色泽和汤花（泡沫）的形态","品饮：趁热啜饮，感受茶味"]'::jsonb),
    ('文人品茶礼', '文人雅集', '文人品茶讲究"清、雅、静、和"，注重环境、心境、茶友的和谐统一。', '["择境：选择清幽雅致的环境，窗外有竹、室内有琴最佳","布席：铺设茶席，陈列茶器，插花挂画","焚香：点燃沉香或檀香，净化空气，安定心神","听琴：抚琴或放古琴音乐，营造氛围","煮水：用陶壶或铁壶煮水，听水声辨水温","赏茶：观察干茶外形、色泽、香气","冲泡：以适宜的注水手法冲泡","分茶：将茶汤均匀分入杯中","品茗：先观色、再闻香、后品味","论茶：品评茶味，交流心得","记感：记录品茶感受，即兴赋诗"]'::jsonb),
    ('婚礼茶礼', '婚嫁礼仪', '茶在中国传统婚礼中具有特殊意义。"茶不移本，植必生子"——古人以茶象征忠贞不渝的爱情和多子多福。', '["备茶：准备上等茶叶，寓意美满","敬茶：新郎新娘双手捧茶，敬奉父母","改口：父母喝过茶后，正式改口称呼","受礼：父母饮茶后给予祝福和红包","对饮：新婚夫妇对饮一杯茶，象征同心"]'::jsonb),
    ('禅茶一味', '寺院茶礼', '"茶禅一味"是中国茶文化的至高境界。僧人以茶修行，通过泡茶、品茶的过程体悟禅理。"吃茶去"是唐代赵州禅师的著名公案。', '["净手：洗净双手，身心清净","入席：盘腿端坐，收摄心神","焚香：一炷清香，清净道场","煮水：听水声，观水汽，心随水静","洗茶：用开水冲洗茶叶，洗去尘埃","冲泡：注水时心无旁骛，专注当下","奉茶：双手举杯齐眉，恭敬奉茶","品茶：不评论、不比较，只是品味","收杯：品毕，静坐片刻，回味余韵"]'::jsonb),
    ('贡茶进献礼', '宫廷贡茶', '贡茶制度始于唐代，盛于宋、明、清。每年春季，茶区精选最好的茶叶进贡皇室，形成了一套严格的礼仪。', '["选茶：茶区官员精选上等茶叶，一芽一叶为标准","包装：用锡罐或瓷罐密封包装，防潮防变","题封：在包装上题写茶名、产地、年份","启程：择吉日，由专人护送进京","呈献：在太和殿或御前呈献贡茶","御品：皇上亲自品鉴，评定等级","赏赐：将贡茶分赐王公大臣"]'::jsonb),
    ('回礼谢茶', '收礼回谢', '收到别人赠茶后，应当以适当的方式回礼表示感谢，这是中国人"礼尚往来"的传统。', '["品鉴：认真品鉴收到的茶叶","致谢：向赠茶人表达感谢","回赠：择日回赠自己的好茶或茶器","分享：将品茶感受分享给赠茶人"]'::jsonb),
    ('敬茶礼仪', '长幼尊卑', '在中国传统礼仪中，敬茶有严格的顺序和方式，体现了长幼尊卑的伦常。', '["长者优先：茶先敬长辈，再敬平辈，最后自饮","双手奉茶：用双手端杯奉于客人面前，杯柄朝向客人右手","七分满：茶斟七分满，\"酒满敬人，茶满欺人\"","续茶及时：客人杯剩三分之一时及时续水","屈指叩桌：受茶者以食指中指轻叩桌面三下表示感谢"]'::jsonb),
    ('夏日新茶会', '季节茶会', '夏日新茶会是文人雅士在夏季举办的品茶雅集，以新茶消暑，以诗文会友。', '["择日：选夏日清凉之日","备茶：准备当季新茶和时令茶点","设席：在庭院或水榭中设茶席","品新：品鉴当年新制春茶","赋诗：即兴作茶诗","馈赠：互赠新茶作为纪念"]'::jsonb),
    ('冬日围炉茶话', '冬日茶会', '冬日围炉煮茶是中国传统的冬日雅事，一炉炭火、一壶老茶，三五好友，最是温暖。', '["备炭：准备上等炭火，无烟耐燃","架壶：将陶壶或铁壶架于炭炉上","煮水：听水声从\"蟹眼\"到\"鱼眼\"到\"松涛\"","投茶：将茶叶投入壶中","煮茶：慢火熬煮，茶香四溢","分茶：将煮好的茶汤分入各杯","品茗：趁热品饮，茶暖身心","话旧：围炉夜话，谈天说地"]'::jsonb),
    ('送茶别礼', '送别赠茶', '以茶为赠别的礼物，在中国传统文化中寓意深远——"君子之交淡如水"。', '["选茶：选择寓意美好的茶（如普洱象征越陈越香）","包装：用宣纸或竹筒精心包装","题字：在包装上题写祝福语或诗句","赠别：临别时将茶赠予友人","寄语：附上一张茶笺，写明茶的冲泡方法"]'::jsonb),
    ('新春拜年茶', '春节礼仪', '春节期间以茶待客是中国人的传统习俗，"茶"寓意清吉平安，"拜年茶"承载着对新年的美好祝愿。', '["备年茶：准备上好茶叶和茶点","迎客：开门迎客，互道新年祝福","奉茶：双手奉上热茶","品茶叙旧：边品茶边话家常","赠茶：客人离去时赠送小包装茶礼"]'::jsonb),
    ('九曲茶会', '文人雅集', '九曲茶会源自东晋"曲水流觞"的文人雅集传统，以茶代酒，沿着蜿蜒的水渠品茶赋诗。', '["选址：在蜿蜒的溪流旁设席","布器：沿溪放置茶席和茶具","流杯：将茶盏放在莲叶上顺流而下","取杯：茶盏流到谁面前，谁取杯品饮","赋诗：品茶后即兴作诗一首","续杯：将茶盏重新放入水中，继续流转"]'::jsonb);
